<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const projectMatch = location.pathname.match(/^\/projects\/(\d+)$/);

    async function request(url, options) {
      const response = await fetch(url, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    }

    function escapeText(value) {
      const element = document.createElement('span');
      element.textContent = value;
      return element.innerHTML;
    }

    async function showProjects(selectedFilter = 'Active') {
      const projects = await request('/api/projects');
      app.innerHTML = `
        <h1>Workboard</h1>
        <form id="create-project">
          <div class="field"><label for="project-name">Project name</label><input id="project-name" name="name" type="text"></div>
          <button type="submit">Create project</button>
        </form>
        <p id="error" role="alert" hidden></p>
        <div class="task-controls"><div><label for="project-filter">Project filter</label><select id="project-filter"><option>Active</option><option>Archived</option></select></div></div>
        <section class="project-list" aria-label="Projects">
        </section>`;
      const list = app.querySelector('.project-list');
      const filter = app.querySelector('#project-filter');
      filter.value = selectedFilter;
      function renderProjects() {
        const archived = filter.value === 'Archived';
        list.innerHTML = projects.filter(project => project.archived === archived).map(project => `<div data-testid="project-row"><span>${escapeText(project.name)}</span><span data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span><button type="button" data-project-id="${project.id}">Open project</button><button type="button" data-archive-id="${project.id}">${archived ? 'Restore project' : 'Archive project'}</button></div>`).join('');
        list.querySelectorAll('[data-project-id]').forEach(button => button.addEventListener('click', () => {
          location.href = `/projects/${button.dataset.projectId}`;
        }));
        list.querySelectorAll('[data-archive-id]').forEach(button => button.addEventListener('click', async () => {
          const action = archived ? 'restore' : 'archive';
          try {
            await request(`/api/projects/${button.dataset.archiveId}/${action}`, { method: 'POST' });
            await showProjects(archived ? 'Archived' : 'Active');
          } catch (problem) {
            const error = app.querySelector('#error');
            error.textContent = problem.message;
            error.hidden = false;
          }
        }));
      }
      filter.addEventListener('change', renderProjects);
      renderProjects();

      app.querySelector('#create-project').addEventListener('submit', async event => {
        event.preventDefault();
        const input = app.querySelector('#project-name');
        const error = app.querySelector('#error');
        try {
          await request('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name: input.value }) });
          await showProjects();
        } catch (problem) {
          error.textContent = problem.message;
          error.hidden = false;
        }
      });
    }

    async function showProject(id) {
      try {
        const project = await request(`/api/projects/${id}`);
        const tasks = await request(`/api/projects/${id}/tasks`);
        const archived = project.archived;
        app.innerHTML = `
          <button class="back" type="button">Projects</button>
          <h1>${escapeText(project.name)}</h1>
          ${archived ? '<p>Archived project</p>' : ''}
          <form id="create-task">
            <div class="field"><label for="task-title">Task title</label><input id="task-title" name="title" type="text"></div>
            <button type="submit">Create task</button>
          </form>
          <p id="error" role="alert" hidden></p>
