          const visibleTasks = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === task.completed);
          list.innerHTML = visibleTasks.map(task => `<div data-testid="task-row"><input type="checkbox" aria-label="Complete ${escapeText(task.title)}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''} ${archived ? 'disabled' : ''}><span>${escapeText(task.title)}</span></div>`).join('');
          list.querySelectorAll('[data-task-id]').forEach(checkbox => checkbox.addEventListener('change', async () => {
            const task = tasks.find(item => item.id === Number(checkbox.dataset.taskId));
            try {
              await request(`/api/projects/${id}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
              task.completed = checkbox.checked;
              renderTasks();
            } catch (problem) {
              checkbox.checked = task.completed;
              const error = app.querySelector('#error');
              error.textContent = problem.message;
              error.hidden = false;
            }
          }));
        }
        filter.addEventListener('change', renderTasks);
        renderTasks();
        app.querySelector('#create-task').addEventListener('submit', async event => {
          event.preventDefault();
          const input = app.querySelector('#task-title');
          const error = app.querySelector('#error');
          try {
            const task = await request(`/api/projects/${id}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: input.value }) });
            tasks.push(task);
            input.value = '';
            error.hidden = true;
            renderTasks();
          } catch (problem) {
            error.textContent = problem.message;
            error.hidden = false;
          }
        });
      } catch {
        app.innerHTML = '<h1>Project not found</h1><button class="back" type="button">Projects</button>';
        app.querySelector('button').addEventListener('click', () => { location.href = '/'; });
      }
    }

    if (projectMatch) showProject(projectMatch[1]);
    else showProjects();
  </script>
